SELECT EXISTS(
    SELECT 1
    FROM t_group
    WHERE id = #{groupId}
      AND user_id = #{userId}
      AND deleted_at IS NULL
)

SELECT EXISTS(
    SELECT 1
    FROM t_link
    WHERE id = #{linkId}
)

SELECT EXISTS(
    SELECT 1
    FROM t_link
    WHERE short_domain_id = #{shortDomainId}
      AND link_code = #{linkCode}
)
